import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

export default function LevelsPage() {
  const [levels, setLevels] = useState([]);
  const navigate = useNavigate();

  const completed =
    JSON.parse(localStorage.getItem("completedLevels")) || [];

  const isUnlocked = (level) =>
    level === 1 || completed.includes(level - 1);

  useEffect(() => {
    fetch("http://localhost:5000/problem")
      .then(res => res.json())
      .then(setLevels);
  }, []);

  return (
    <div style={{ color:"white" }}>
      <h1>Levels</h1>
      <table border="1" cellPadding="10">
        <thead>
          <tr><th>Level</th><th>Title</th><th>Action</th></tr>
        </thead>
        <tbody>
          {levels.map(l => {
            const done = completed.includes(l.level);
            return (
              <tr
                key={l.id}
                style={{ background: done ? "lightgreen" : "transparent" }}
              >
                <td>{l.level}</td>
                <td>{l.title}</td>
                <td>
                  <button
                    disabled={!isUnlocked(l.level)}
                    onClick={() => navigate(`/manaco-editor/${l.level}`)}
                  >
                    {done ? "Completed" : isUnlocked(l.level) ? "Start" : "Locked"}
                  </button>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
